{
  "items": [
    {
      "path": "tools.browse.session_list",
      "description": "List browse sessions.",
      "signature": "tools.browse.session_list(): Promise<{
  sessions: Array<{
      id: string,
      createdAt: string,
      updatedAt: string,
      connected: boolean,
      pageUrl: string | null,
      stateKeys: Array<string>,
      readOnly?: boolean,
      allowedOrigins?: Array<string>,
      browser?: string,
    }>,
}>"
    },
    {
      "path": "tools.browse.session_allowlist",
      "description": "Set the domain allowlist of a session (the current one by default): the hosts or origins its tabs may load. Pass an empty list to remove it. Use it before typing secrets or working on sites with untrusted content.",
      "signature": "tools.browse.session_allowlist({
  /** Session id; defaults to the current session. */
  session?: string,
  /**
   * Patterns: example.com, *.example.com, https://app.example.com, http://localhost:3000. Empty removes the allowlist.
   */
  allowedOrigins: Array<string>,
}): Promise<{
  session: {
    id: string,
    createdAt: string,
    updatedAt: string,
    connected: boolean,
    pageUrl: string | null,
    stateKeys: Array<string>,
    readOnly?: boolean,
    allowedOrigins?: Array<string>,
    browser?: string,
  },
}>"
    },
    {
      "path": "tools.browse.session_new",
      "description": "Create a browse session and make it your current one. Other agents keep theirs.",
      "signature": "tools.browse.session_new({
  /**
   * Optional browser id for a new session's tabs; omit for the default browser. A session stays in its browser. Call status to list the connected browsers.
   */
  browser?: string,
  /** Optional lowercase session id. */
  id?: string,
  /**
   * Create a read-only session: adopt a tab the user has lent you, then snapshot, screenshot and read it; CDP input, navigation, new pages and cookie writes are refused.
   */
  readOnly?: boolean,
  /**
   * Optional domain allowlist: hosts or origins this session's tabs may load (example.com, *.example.com, https://app.example.com, http://localhost:3000). Navigations elsewhere are refused or sent back to about:blank; private and loopback addresses need an exact entry.
   */
  allowedOrigins?: Array<string>,
}): Promise<{
  session: {
    id: string,
    createdAt: string,
    updatedAt: string,
    connected: boolean,
    pageUrl: string | null,
    stateKeys: Array<string>,
    readOnly?: boolean,
    allowedOrigins?: Array<string>,
    browser?: string,
  },
}>"
    },
    {
      "path": "tools.browse.secrets_list",
      "description": "List what agents may type without seeing: site secrets the user stored (names, kinds and allowed origins; type them with secrets.type(target, name) in execute; only the user adds them with `browse secrets add`).",
      "signature": "tools.browse.secrets_list({
  /** Optional session id. Defaults to this MCP server's current session. */
  session?: string,
}): Promise<{
  secrets: Array<{
      name: string,
      kind: "password" | "totp",
      allowedOrigins: Array<string>,
      createdAt: string,
      updatedAt: string,
    }>,
}>"
    },
    {
      "path": "tools.browse.execute",
      "description": "Execute Playwright JavaScript against the browse session. Code runs in a restricted JavaScript realm on the relay without process, require, import(), fs, child_process, http/https or Node fetch; save and read files with the files helper inside the execute file roots, and cookie access is limited to the session's pages. Synchronous code stops after about 2 seconds. It is not a security boundary, so treat code as running as the user. The result includes console logs, warnings, a bounded execution-context diagnostic when relevant, and an aftermath summary (URL movement, navigations, error counts, handoffs, and a bot challenge or block page when one appears: hand interactive ones to the user with handoff(), never solve or retry-loop them).",
      "signature": "tools.browse.execute({
  /**
   * JavaScript code to execute. It receives browser, context, page, state, modules (path, url, util, crypto, buffer, zlib, events, stream), files (dir and roots properties; path(name), write(target, data), read(target, encoding?)), fillInput, fillInputs, snapshot(options?) for compact semantic outlines (options: find to search them, diff or delta for changes), persistent compatible ref(id) locators, webmcp (list/call), screenshotWithLabels(options?) and screenshotDiff(options) for screenshots, ariaSnapshot, ghostCursor, handoff, demonstrate, network (start/status/stop/cancel), pageConsole (start/stop capturing the page's own console messages and errors, off by default because pages can detect it), and secrets.type(locator, name) to type a stored site secret (see secrets_list) only on its allowed origins, without seeing it. There is no location, document or fetch global (they belong to the page: use page.url() or page.evaluate(...)), and no structuredClone.
   */
  code: string,
  /**
   * Optional existing browse session id. Explicit ids must already exist; omit this field to use your current session (each agent has its own), which is created when needed.
   */
  session?: string,
  /**
   * Optional URL substring selecting an existing attached page. This does not navigate or open a URL; use page.goto() for that.
   */
  targetUrl?: string,
  /** Optional zero-based attached page index selector. @integer @minimum 0 */
  targetIndex?: number,
  /**
   * Optional browser id for a new session's tabs; omit for the default browser. A session stays in its browser. Call status to list the connected browsers.
   */
  browser?: string,
  /**
   * Optional overall script timeout in milliseconds (paused while handoff() waits on the user); defaults to 60000, 0 disables.
   * @integer @minimum 0
   */
  timeoutMs?: number,
}): Promise<{
  session: string,
  value?: unknown,
  logs?: Array<{
      source: "script" | "page",
      type: string,
      text: string,
      location?: {
        url: string,
        lineNumber: number,
        columnNumber: number,
      },
      repeatCount?: number,
    }>,
  logSummary?: {
    totalCount: number,
    returnedCount: number,
    repeatedCount: number,
    omittedCount: number,
  },
  warnings?: Array<string>,
  diagnostic?: string,
  aftermath?: {
    startUrl: string | null,
    endUrl: string | null,
    navigations: Array<string>,
    consoleErrorCount: number,
    pageErrorCount: number,
    handoffs: number,
    challenge?: {
      vendor: string,
      kind: "non-interactive" | "interactive" | "block",
      status: "cleared" | "blocked",
      signal: string,
      url: string,
      waitedMs: number,
      recommendation: "continue" | "handoff" | "stop",
    },
  },
  notice?: string,
}>"
    },
    {
      "path": "tools.browse.session_adopt",
      "description": "Make an attached tab the browse session's default page for subsequent bare execute calls. Omit targetUrl and targetIndex when only one user-attached tab is available.",
      "signature": "tools.browse.session_adopt({
  /**
   * Optional existing browse session id. Explicit ids must already exist; omit this field to use your current session, which is created when needed.
   */
  session?: string,
  /**
   * Adopt an existing attached page whose URL contains this text. Omit when only one user-attached tab is available. This does not navigate or open a URL.
   */
  targetUrl?: string,
  /** Adopt the attached page at this zero-based target index. @integer @minimum 0 */
  targetIndex?: number,
  /** Adopt the user's tab with this Chrome tab id (the tab= value in status). @integer */
  tabId?: number,
}): Promise<{
  session: {
    id: string,
    createdAt: string,
    updatedAt: string,
    connected: boolean,
    pageUrl: string | null,
    stateKeys: Array<string>,
    readOnly?: boolean,
    allowedOrigins?: Array<string>,
    browser?: string,
    created?: boolean,
  },
  adoptedUrl: string,
  adoptedTargetId: string,
}>"
    },
    {
      "path": "tools.browse.session_delete",
      "description": "Delete a browse session.",
      "signature": "tools.browse.session_delete({
  /** Optional session id. Defaults to this MCP server's current session. */
  id?: string,
  /** Same as id. */
  session?: string,
}): Promise<{
  deleted: boolean,
  id: string,
  stopped?: {
    execute: boolean,
    handoff: boolean,
    forced: boolean,
  },
  currentSession: string,
}>"
    },
    {
      "path": "tools.browse.session_reset",
      "description": "Reset a browse session's state and page.",
      "signature": "tools.browse.session_reset({
  /** Optional session id. Defaults to this MCP server's current session. */
  id?: string,
  /** Same as id. */
  session?: string,
}): Promise<{
  session: {
    id: string,
    createdAt: string,
    updatedAt: string,
    connected: boolean,
    pageUrl: string | null,
    stateKeys: Array<string>,
    readOnly?: boolean,
    allowedOrigins?: Array<string>,
    browser?: string,
  },
  stopped?: {
    execute: boolean,
    handoff: boolean,
    forced: boolean,
  },
}>"
    },
    {
      "path": "tools.browse.session_use",
      "description": "Make an existing browse session your current one, for calls that don't name a session. Other agents keep theirs; pass `session` explicitly to share one deliberately.",
      "signature": "tools.browse.session_use({
  /** Existing browse session id. */
  id: string,
}): Promise<{
  currentSession: string,
}>"
    },
    {
      "path": "tools.browse.network",
      "description": "Start, inspect, stop, or cancel session-scoped network capture. browse records normalized Playwright exchanges; HAR is only the optional export format. Bodies are embedded by default with per-body and total memory limits. Actions: start begins a capture; status returns bounded metadata for the active capture without captured values; stop ends it and optionally writes a credential-redacted HAR and stores lossless credential values in a reusable secret profile (at least one of outputPath or secrets is required); cancel ends it and discards the in-memory exchanges.",
      "signature": "tools.browse.network({
  /**
   * start begins a capture, status reports its bounded metadata, stop writes a redacted HAR and/or secret profile, cancel discards it.
   */
  action: "start" | "status" | "stop" | "cancel",
  /** Optional session id. Defaults to this MCP server's current session; start creates it when missing. */
  session?: string,
  /** For start: capture only request URLs containing this text. */
  urlFilter?: string,
  /** For start: optional Playwright resource types such as fetch and xhr. */
  resourceTypes?: Array<string>,
  /** For start: request and response body mode. Defaults to embed. */
  content?: "embed" | "omit",
  /** For start: maximum bytes captured from each body. Defaults to 1000000. @integer @minimum 1 */
  maxBodyBytes?: number,
  /** For start: maximum body bytes retained for the capture. Defaults to 25000000. @integer @minimum 1 */
  maxTotalBodyBytes?: number,
  /** For start: maximum captured requests. Defaults to 1000. @integer @minimum 1 */
  maxEntries?: number,
  /**
   * For start: the capture ends by itself, discarding what it captured, after this long. Defaults to 1800000 (30 minutes). It also ends when this MCP server exits.
   * @integer @minimum 1 @maximum 86400000
   */
  maxDurationMs?: number,
  /**
   * For stop: optional artifact path, resolved against the MCP process working directory. The HAR contains stable ${BC_SECRET_N} references (and redaction-only ${BC_REDACTED_N} for passwords, one-time codes and token-like URL path segments), not captured values.
   */
  outputPath?: string,
  /** For stop: optional reusable profile name for captured credential values. */
  secrets?: string,
}): Promise<{
  action: "start" | "status" | "stop" | "cancel",
  session: string,
  active?: boolean,
  startedAt?: string,
  entryCount?: number,
  responseCount?: number,
  failureCount?: number,
  capturedBodyBytes?: number,
  truncatedBodyCount?: number,
  droppedEntryCount?: number,
  urlFilter?: string,
  resourceTypes?: Array<string>,
  content?: "omit" | "embed",
  secrets?: string,
  endsAt?: string,
  ended?: string,
  stoppedAt?: string,
  outputPath?: string,
  authProfile?: {
    name: string,
    createdAt: string,
    updatedAt: string,
    slotCount: number,
    slots: Array<{
        ref: string,
        sources: Array<string>,
        expiresAt?: string,
        expired: boolean,
      }>,
  },
  updatedSecretRefs?: Array<string>,
  observedSecretRefs?: Array<string>,
  endpoints?: Array<{
      method: string,
      url: string,
      status?: number,
      count: number,
      requestHeaders?: Array<string>,
      requestKeys?: Array<string>,
      responseKeys?: Array<string>,
    }>,
  cancelled?: boolean,
}>"
    },
    {
      "path": "tools.browse.flight_recorder",
      "description": "Keep a rolling in-memory video buffer for the current session tab. Actions: start begins buffering; status returns bounded rolling-buffer duration, frame, byte and drop counters; save_last encodes and saves the most recent buffered video without stopping the buffer (outputPath is required); cancel stops and discards the buffer.",
      "signature": "tools.browse.flight_recorder({
  /** start begins buffering, status reports, save_last saves a clip, cancel discards the buffer. */
  action: "start" | "status" | "save_last" | "cancel",
  /** Optional session id. Defaults to this MCP server's current session. */
  session?: string,
  /** For start: rolling retention window. Defaults to 60000. @integer @minimum 1000 @maximum 120000 */
  retentionMs?: number,
  /** For start: saved clip frame rate. Defaults to 60. @integer @minimum 1 @maximum 60 */
  frameRate?: number,
  /** For start: draw the ghost cursor in the buffered video. Off by default. */
  cursor?: boolean,
  /** For save_last: fresh .webm or .mp4 path, resolved against the MCP process working directory. */
  outputPath?: string,
  /** For save_last: recent duration to save. Defaults to 30000 and cannot exceed retention. @integer @minimum 1 */
  durationMs?: number,
}): Promise<{
  action: "start" | "status" | "save_last" | "cancel",
  session: string,
  active?: boolean,
  tabId?: number,
  sessionId?: string,
  startedAt?: number,
  retentionMs?: number,
  retainedDurationMs?: number,
  frameRate?: number,
  bufferedFrames?: number,
  bufferedBytes?: number,
  sourceFrameCount?: number,
  droppedFrameCount?: number,
  saving?: boolean,
  path?: string,
  durationMs?: number,
  frameCount?: number,
  cancelled?: boolean,
}>"
    },
    {
      "path": "tools.browse.recording",
      "description": "Record the current session tab. Actions: start begins recording (CDP mode records video to WebM or MP4; tab-capture mode supports WebM and optional audio; outputPath is required); stop finalizes the artifact; status returns bounded status and quality counters; cancel discards the unfinished artifact.",
      "signature": "tools.browse.recording({
  /** start begins, stop finalizes, status reports, cancel discards the recording. */
  action: "start" | "stop" | "status" | "cancel",
  /** Optional session id. Defaults to this MCP server's current session. */
  session?: string,
  /** For start: recording artifact path, resolved against the MCP process working directory. */
  outputPath?: string,
  /** For start: recording backend. Defaults to auto. */
  mode?: "auto" | "tab-capture" | "cdp",
  /** For start: capture tab audio in tab-capture mode. */
  audio?: boolean,
  /** For start: requested frame rate. @integer @minimum 1 @maximum 60 */
  frameRate?: number,
  /** For start: maximum recording duration in milliseconds. @integer @minimum 1 */
  maxDurationMs?: number,
  /**
   * For start: draw the ghost cursor in the recording, for demo videos. Off by default: recordings show only the page, with nothing from browse in the frame.
   */
  cursor?: boolean,
}): Promise<{
  action: "start" | "stop" | "status" | "cancel",
  session: string,
  success?: boolean,
  tabId?: number,
  startedAt?: number,
  path?: string,
  mimeType?: string,
  mode?: "tab-capture" | "cdp",
  artifactType?: "webm" | "mp4",
  frameRate?: number,
  duration?: number,
  size?: number,
  frameCount?: number,
  quality?: {
    width: number,
    height: number,
    frameRate: number,
    sourceFrameCount: number,
    encodedSourceFrameCount: number,
    coalescedFrameCount: number,
    droppedFrameCount: number,
    achievedSourceFrameRate: number,
    achievedEncodedSourceFrameRate: number,
    screenshotFallback: boolean,
    sourceWidth?: number,
    sourceHeight?: number,
  },
  isRecording?: boolean,
  error?: string,
}>"
    },
    {
      "path": "tools.browse.secrets_refresh",
      "description": "Reload a session page, observe fresh credentials, and update a secret profile while preserving stable BC_SECRET_N references.",
      "signature": "tools.browse.secrets_refresh({
  /** Existing secret profile name. */
  name: string,
  /** Optional session id. Defaults to this MCP server's current session. */
  session?: string,
  /** Observe credentials only on matching request URLs. */
  urlFilter?: string,
  /** Reload timeout. Defaults to 30000. @integer @minimum 1 */
  timeoutMs?: number,
}): Promise<{
  active: false,
  startedAt?: string,
  entryCount: number,
  responseCount: number,
  failureCount: number,
  capturedBodyBytes: number,
  truncatedBodyCount: number,
  droppedEntryCount: number,
  urlFilter?: string,
  resourceTypes?: Array<string>,
  content?: "omit" | "embed",
  secrets?: string,
  endsAt?: string,
  ended?: string,
  stoppedAt: string,
  outputPath?: string,
  authProfile?: {
    name: string,
    createdAt: string,
    updatedAt: string,
    slotCount: number,
    slots: Array<{
        ref: string,
        sources: Array<string>,
        expiresAt?: string,
        expired: boolean,
      }>,
  },
  updatedSecretRefs: Array<string>,
  observedSecretRefs: Array<string>,
  endpoints?: Array<{
      method: string,
      url: string,
      status?: number,
      count: number,
      requestHeaders?: Array<string>,
      requestKeys?: Array<string>,
      responseKeys?: Array<string>,
    }>,
}>"
    },
    {
      "path": "tools.browse.settings",
      "description": "Read or change the user's browse settings from the extension's options page: where agent tabs open (window), how they're grouped (grouping), when untouched agent tabs close (idleMinutes), the agent cursor (cursor), human-like input (humanInput) and handoff notifications (handoffNotifications). Update behaviour is not available here: only the user changes it, with `browse settings` or the extension's options page, and `status` reports its current value. Use this tool only when the user asks to change how browse behaves, never on your own initiative. Without `set` it returns each setting's stored value, the value in effect, and the relay environment variable that overrides it, if any. With `set` it validates every value strictly, applies the change at once (the options page updates live) and returns what changed: tell the user what you changed. A setting an environment variable fixes is not changed, and the result says so. Security switches (OPENCODE_BROWSER_ALLOW_NODE, OPENCODE_BROWSER_ALLOW_ALL_COOKIES, OPENCODE_BROWSER_ALLOW_FOREGROUND, OPENCODE_BROWSER_ALLOW_ALL_STORAGE, OPENCODE_BROWSER_ALLOW_FILE_URLS, OPENCODE_BROWSER_UPDATE_CHECK) are environment-only and can never be read or changed here.",
      "signature": "tools.browse.settings({
  /** Settings to change; omit to only read them. */
  set?: {
    /** Where agents open their tabs (current: the user's window; separate: an unfocused window of their own) */
    window?: "current" | "separate",
    /** How agent tabs are grouped (one shared group, one group per session, or none) */
    grouping?: "shared" | "session" | "none",
    /** Close agent tabs untouched for this many minutes */
    idleMinutes?: 10 | 30 | 60 | "never",
    /** Agent cursor on agent tabs outside recordings (pages can detect it) */
    cursor?: "off" | "always",
    /** Human-like input (off is faster, but easier for sites to flag) */
    humanInput?: "on" | "off",
    /** System notification on a handoff (only while recorded, or every handoff) */
    handoffNotifications?: "recording" | "always",
  },
}): Promise<{
  settings: {
    window: {
      value: string | number,
      effective: string | number,
      allowed: Array<string | number>,
      description: string,
      overriddenBy?: string,
    },
    grouping: {
      value: string | number,
      effective: string | number,
      allowed: Array<string | number>,
      description: string,
      overriddenBy?: string,
    },
    idleMinutes: {
      value: string | number,
      effective: string | number,
      allowed: Array<string | number>,
      description: string,
      overriddenBy?: string,
    },
    cursor: {
      value: string | number,
      effective: string | number,
      allowed: Array<string | number>,
      description: string,
      overriddenBy?: string,
    },
    humanInput: {
      value: string | number,
      effective: string | number,
      allowed: Array<string | number>,
      description: string,
      overriddenBy?: string,
    },
    handoffNotifications: {
      value: string | number,
      effective: string | number,
      allowed: Array<string | number>,
      description: string,
      overriddenBy?: string,
    },
  },
  note?: string,
  changed?: Array<{
      key: string,
      from: string | number,
      to: string | number,
    }>,
  unchanged?: Array<string>,
  overridden?: Array<{
      key: string,
      requested: string | number,
      variable: string,
      effective: string | number,
    }>,
  message?: string,
}>"
    },
    {
      "path": "tools.browse.status",
      "description": "Return relay, extension, target, session, and connected browser status.",
      "signature": "tools.browse.status(): Promise<{
  endpoint: string,
  currentSession: string,
  version: {
    version: string,
    buildId?: string,
    instanceId?: string,
    startedAt?: string,
    pid?: number,
    managed?: boolean,
    shutdownProtocol?: 2,
  },
  status: {
    connected: boolean,
    pairingState?: "connected" | "incompatible" | "refused" | "unpaired" | "paired-offline" | "not-seen",
    nextStep?: string,
    version: string | null,
    build?: string | null,
    origin?: string | null,
    protocolVersion?: number | null,
    protocolCompatible?: boolean | null,
    protocolLegacy?: boolean | null,
    browsers?: Array<{
        id: string,
        name: string,
        default: boolean,
        connected: boolean,
        unresponsive?: boolean,
        version: string | null,
        /** @integer @minimum 0 */
        tabs: number,
      }>,
    /** @integer @minimum 0 */
    rejectedConnections?: number,
    /** @integer @minimum 0 */
    pairingFailures?: number,
    processFaults?: {
      /** @integer @minimum 0 */
      suppressed: number,
      lastAt?: string,
      lastMessage?: string,
    },
    activeTargets: number,
    childTargets?: number,
    cdpClients?: number,
    sessions?: Array<{
        id: string,
        createdAt: string,
        updatedAt: string,
        connected: boolean,
        pageUrl: string | null,
        stateKeys: Array<string>,
        readOnly?: boolean,
        allowedOrigins?: Array<string>,
        browser?: string,
      }>,
    targets?: Array<{
        id: string,
        type: string,
        title: string,
        url: string,
        tabId?: number,
        sessionId?: string,
        opencodeBrowserSessionId?: string,
        owner?: "relay" | "user",
        crashed?: boolean,
        protectedUi?: boolean,
      }>,
  },
  buildProblem?: string,
  update?: unknown,
  autoUpdate: unknown,
}>"
    },
    {
      "path": "tools.browse.tabs_cleanup",
      "description": "Close tabs agents opened that nobody has used for a while (no agent command and not visited by the user). Tabs the user shared or pinned, the active tab, tabs playing audio, recording, or waiting for a handoff stay open. `idleMinutes` applies to your own sessions' tabs; other agents' tabs close only once idle for the user's setting too. To finish your own work, `session_reset` or `session_delete` is more direct. browse also does this automatically after the user's idle setting (10 minutes unless they changed it).",
      "signature": "tools.browse.tabs_cleanup({
  /**
   * Close your own sessions' tabs idle at least this long; 0 closes all of them. Defaults to the user's setting (10 minutes; still 10 when the user set automatic cleanup to never).
   * @integer @minimum 0
   */
  idleMinutes?: number,
}): Promise<{
  closed: Array<{
      tabId: number,
      title: string,
      idleMinutes: number,
    }>,
}>"
    },
    {
      "path": "tools.browse.secrets_run",
      "description": "Run a local command with a captured profile injected as BC_SECRET_N environment variables. Known values are replaced with their references in stdout and stderr, which keeps them out of transcripts. The command receives the real values, so redaction does not protect them from a command that deliberately sends or encodes them: run only commands you wrote or trust.",
      "signature": "tools.browse.secrets_run({
  /** Secret profile name. */
  name: string,
  /** Executable path or command name. */
  command: string,
  /** Command arguments. */
  args?: Array<string>,
  /** Optional child working directory. */
  cwd?: string,
  /** Child timeout. Defaults to 120000. @integer @minimum 1 */
  timeoutMs?: number,
}): Promise<{
  exitCode: number,
  signal: string | null,
  stdout: string,
  stderr: string,
  stdoutTruncated: boolean,
  stderrTruncated: boolean,
  durationMs: number,
}>"
    },
    {
      "path": "tools.browse.secrets_status",
      "description": "Return secret profile references, sources, and expiration metadata without revealing credential values.",
      "signature": "tools.browse.secrets_status({
  /** Secret profile name. */
  name: string,
}): Promise<{
  name: string,
  createdAt: string,
  updatedAt: string,
  slotCount: number,
  slots: Array<{
      ref: string,
      sources: Array<string>,
      expiresAt?: string,
      expired: boolean,
    }>,
}>"
    }
  ],
  "remaining": 0,
  "next": null
}

